+      const url = `${origin}${walletPrefix}${encodeURIComponent(account)}/summary`;
+      const payload = await requestJSON(url, { 'X-Member-Token': member.token });
+
+      if (!isSummaryFor(payload, provider, account)) throw upstreamFailure();
